import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, AppSettings, Gift, Page, INITIAL_SETTINGS, INITIAL_GIFTS, INITIAL_PAGES } from './types';

interface StoreContextType extends AppState {
  updateSettings: (settings: Partial<AppSettings>) => void;
  addGift: (gift: Omit<Gift, 'id' | 'purchasedCount'>) => void;
  removeGift: (id: string) => void;
  purchaseGift: (id: string) => void;
  addPage: (page: Page) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  removePage: (id: string) => void;
  resetStore: () => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Load from localStorage or use defaults
  const loadState = (): AppState => {
    const stored = localStorage.getItem('wedding_site_store');
    if (stored) {
      return JSON.parse(stored);
    }
    return {
      settings: INITIAL_SETTINGS,
      gifts: INITIAL_GIFTS,
      pages: INITIAL_PAGES
    };
  };

  const [state, setState] = useState<AppState>(loadState);

  // Save to localStorage whenever state changes
  useEffect(() => {
    localStorage.setItem('wedding_site_store', JSON.stringify(state));
  }, [state]);

  const updateSettings = (newSettings: Partial<AppSettings>) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, ...newSettings } }));
  };

  const addGift = (gift: Omit<Gift, 'id' | 'purchasedCount'>) => {
    const newGift: Gift = {
      ...gift,
      id: crypto.randomUUID(),
      purchasedCount: 0
    };
    setState(prev => ({ ...prev, gifts: [...prev.gifts, newGift] }));
  };

  const removeGift = (id: string) => {
    setState(prev => ({ ...prev, gifts: prev.gifts.filter(g => g.id !== id) }));
  };

  const purchaseGift = (id: string) => {
    setState(prev => ({
      ...prev,
      gifts: prev.gifts.map(g => g.id === id ? { ...g, purchasedCount: g.purchasedCount + 1 } : g)
    }));
  };

  const addPage = (page: Page) => {
    setState(prev => ({ ...prev, pages: [...prev.pages, page] }));
  };

  const updatePage = (id: string, updatedPage: Partial<Page>) => {
    setState(prev => ({
      ...prev,
      pages: prev.pages.map(p => p.id === id ? { ...p, ...updatedPage } : p)
    }));
  };

  const removePage = (id: string) => {
    setState(prev => ({ ...prev, pages: prev.pages.filter(p => p.id !== id) }));
  };

  const resetStore = () => {
    setState({
      settings: INITIAL_SETTINGS,
      gifts: INITIAL_GIFTS,
      pages: INITIAL_PAGES
    });
  };

  return (
    <StoreContext.Provider value={{
      ...state,
      updateSettings,
      addGift,
      removeGift,
      purchaseGift,
      addPage,
      updatePage,
      removePage,
      resetStore
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import { GoogleGenAI, Type } from "@google/genai";
import { Page, Section } from "../types";

const SYSTEM_INSTRUCTION = `
You are an expert web designer and copywriter for high-end weddings. 
Your goal is to generate JSON content for a new wedding website page.
The style should be romantic, elegant, classic, and welcoming.
The content must be coherent with the provided existing pages.
Output strictly JSON.
`;

export const generatePageContent = async (
  topic: string,
  existingPages: Page[],
  apiKey: string
): Promise<Page> => {
  if (!apiKey) throw new Error("API Key is missing");

  const ai = new GoogleGenAI({ apiKey });

  const prompt = `
    I need a new page for a wedding website about: "${topic}".

    Here is the context of the existing site content:
    ${JSON.stringify(existingPages.map(p => ({ title: p.title, sections: p.sections.map(s => s.content) })))}

    Please generate a valid JSON object for a single 'Page'.

    The JSON schema must follow this TypeScript interface:
    interface Page {
      id: string; // generate a random UUID string
      title: string;
      slug: string; // should start with /
      isSystem: boolean; // always false
      sections: Array<{
        id: string; // generate a random UUID string
        type: 'hero' | 'text' | 'image-text' | 'gallery';
        title?: string;
        content?: string;
        imageUrl?: string; // Use https://picsum.photos/width/height
        imagePosition?: 'left' | 'right';
      }>
    }

    Rules:
    1. Use 'hero' for the top section.
    2. Write romantic, inviting copy in Portuguese (pt-BR).
    3. Ensure the tone matches the existing pages.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-latest",
      contents: prompt,
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
         // We define the schema to ensure strict type compliance
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            title: { type: Type.STRING },
            slug: { type: Type.STRING },
            isSystem: { type: Type.BOOLEAN },
            sections: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING },
                  type: { type: Type.STRING, enum: ['hero', 'text', 'image-text', 'gallery'] },
                  title: { type: Type.STRING, nullable: true },
                  content: { type: Type.STRING, nullable: true },
                  imageUrl: { type: Type.STRING, nullable: true },
                  imagePosition: { type: Type.STRING, enum: ['left', 'right'], nullable: true },
                },
                required: ['id', 'type']
              }
            }
          },
          required: ['id', 'title', 'slug', 'isSystem', 'sections']
        }
      },
    });

    if (response.text) {
      const pageData = JSON.parse(response.text) as Page;
      // Force isSystem to false for generated pages to avoid overwriting core routes
      pageData.isSystem = false;
      return pageData;
    }
    throw new Error("No content generated");
  } catch (error) {
    console.error("Gemini generation error:", error);
    throw error;
  }
};

import React, { useEffect, useRef } from 'react';
import { X } from 'lucide-react';

interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
}

export const Modal: React.FC<ModalProps> = ({ isOpen, onClose, title, children }) => {
  const modalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose();
    };

    if (isOpen) {
      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden';
    }

    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = 'unset';
    };
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-stone-900/60 backdrop-blur-sm transition-opacity">
      <div 
        ref={modalRef}
        className="bg-wedding-50 w-full max-w-lg rounded-sm shadow-2xl border border-wedding-200 transform transition-all animate-fade-in-up"
        role="dialog"
        aria-modal="true"
      >
        <div className="flex items-center justify-between p-4 border-b border-wedding-200">
          <h3 className="text-xl font-serif text-wedding-800">{title}</h3>
          <button 
            onClick={onClose}
            className="p-1 text-wedding-600 hover:text-wedding-800 hover:bg-wedding-100 rounded-full transition-colors"
          >
            <X size={24} />
          </button>
        </div>
        <div className="p-6">
          {children}
        </div>
      </div>
    </div>
  );
};

