export const DynamicPage: React.FC = () => {
  const { pages } = useStore();
  const location = window.location.hash.replace('#', '') || '/';

  // Find page by slug
  const page = pages.find(p => p.slug === location);

  if (!page) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <h1 className="font-serif text-4xl text-wedding-800 mb-4">Página não encontrada</h1>
          <p className="text-wedding-600">A página que você procura não existe.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in">
      {page.sections.map(section => {
        switch (section.type) {
          case 'hero': return <HeroSection key={section.id} section={section} />;
          case 'text': return <TextSection key={section.id} section={section} />;
          case 'image-text': return <ImageTextSection key={section.id} section={section} />;
          default: return <TextSection key={section.id} section={section} />;
        }
      })}
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Modal } from '../components/Modal';
import { QRCodeSVG } from 'qrcode.react';
import { Gift, Heart } from 'lucide-react';

export const GiftsPage: React.FC = () => {
  const { gifts, settings, purchaseGift } = useStore();
  const [selectedGift, setSelectedGift] = useState<string | null>(null);

  const handleOpenGift = (giftId: string) => {
    setSelectedGift(giftId);
  };

  const handleConfirmPurchase = () => {
    if (selectedGift) {
      purchaseGift(selectedGift);
      // Keep modal open to show QR code, user manually closes it
    }
  };

  const activeGift = gifts.find(g => g.id === selectedGift);

  const PixCopyPaste = ({ pixKey }: { pixKey: string }) => {
     const [copied, setCopied] = useState(false);

     const copyToClipboard = () => {
        navigator.clipboard.writeText(pixKey);
        setCopied(true);
        setTimeout(() => setCopied(false), 2000);
     };

     return (
        <div className="mt-4 p-3 bg-wedding-100 rounded text-center cursor-pointer hover:bg-wedding-200 transition" onClick={copyToClipboard}>
           <p className="text-xs text-wedding-500 uppercase tracking-wide mb-1">Chave Pix ({settings.pixKeyType})</p>
           <p className="font-mono text-wedding-900 break-all">{pixKey}</p>
           <p className="text-xs text-wedding-600 mt-2 font-bold">{copied ? "Copiado!" : "Clique para copiar"}</p>
        </div>
     );
  }

  return (
    <div className="min-h-screen bg-wedding-50 py-12 animate-fade-in">
      {/* Header */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-16 text-center">
        <h1 className="font-script text-6xl text-wedding-800 mb-6">Lista de Presentes</h1>
        <p className="font-serif text-wedding-600 text-lg max-w-2xl mx-auto">
          Sua presença é o nosso maior presente. Mas se quiserem nos agraciar com um mimo para o início da nossa vida a dois, ficaremos muito felizes!
        </p>
      </div>

      {/* Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {gifts.map((gift) => (
            <div key={gift.id} className="bg-white rounded-sm shadow-md overflow-hidden hover:shadow-xl transition-shadow duration-300 border border-wedding-100 group">
              <div className="h-64 overflow-hidden relative">
                <img 
                  src={gift.imageUrl} 
                  alt={gift.name} 
                  className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" 
                />
                <div className="absolute top-0 right-0 bg-wedding-500 text-white px-3 py-1 m-2 text-sm font-bold shadow-sm">
                  R$ {gift.price.toFixed(2)}
                </div>
              </div>
              <div className="p-6 text-center">
                <h3 className="font-serif text-xl text-wedding-800 mb-2">{gift.name}</h3>
                <p className="text-wedding-600 text-sm mb-6 line-clamp-2 h-10">{gift.description}</p>
                <button
                  onClick={() => handleOpenGift(gift.id)}
                  className="w-full bg-wedding-800 hover:bg-wedding-600 text-white font-serif py-3 px-6 transition-colors flex items-center justify-center gap-2 uppercase tracking-widest text-xs"
                >
                  <Gift size={16} />
                  Faça os noivos felizes
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Modal */}
      <Modal 
        isOpen={!!selectedGift} 
        onClose={() => setSelectedGift(null)}
        title="Presentear os Noivos"
      >
        {activeGift && (
          <div className="text-center space-y-6">
            <div className="bg-wedding-50 p-4 rounded-full w-20 h-20 mx-auto flex items-center justify-center text-wedding-500">
              <Heart size={40} fill="currentColor" />
            </div>

            <div>
              <h4 className="font-serif text-2xl text-wedding-800 mb-2">Muito Obrigado!</h4>
              <p className="text-wedding-600">
                Para confirmar o presente <strong>{activeGift.name}</strong>, por favor utilize o QR Code abaixo para realizar o Pix no valor de:
              </p>
              <p className="text-3xl font-serif text-wedding-800 mt-4">
                R$ {activeGift.price.toFixed(2)}
              </p>
            </div>

            <div className="flex justify-center p-4 bg-white border border-wedding-200 inline-block mx-auto">
               {/* 
                  NOTE: In a real app, you would generate a specific Payload string for Pix (EMV format).
                  Here we just encode the key or a dummy string for visual representation.
               */}
              <QRCodeSVG value={settings.pixKey} size={200} fgColor={settings.primaryColor} />
            </div>

            <PixCopyPaste pixKey={settings.pixKey} />

            <div className="text-sm text-wedding-500 italic">
              Após realizar o Pix, o valor será contabilizado em nossa transparência.
            </div>

            <button
               onClick={() => {
                 handleConfirmPurchase();
                 setSelectedGift(null);
               }}
               className="block w-full text-center text-wedding-800 hover:underline mt-4 text-sm"
            >
              Já realizei o pagamento, fechar.
            </button>
          </div>
        )}
      </Modal>
    </div>
  );
};

import React from 'react';
import { useStore } from '../store';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

export const TransparencyPage: React.FC = () => {
  const { gifts } = useStore();

  const totalGifts = gifts.reduce((acc, curr) => acc + curr.purchasedCount, 0);
  const totalValue = gifts.reduce((acc, curr) => acc + (curr.price * curr.purchasedCount), 0);

  // Prepare data for chart - Top 5 most popular gifts
  const chartData = [...gifts]
    .sort((a, b) => b.purchasedCount - a.purchasedCount)
    .slice(0, 5)
    .map(g => ({
      name: g.name.length > 15 ? g.name.substring(0, 15) + '...' : g.name,
      count: g.purchasedCount
    }));

  return (
    <div className="min-h-screen bg-wedding-50 py-12 animate-fade-in">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-16">
          <h1 className="font-script text-6xl text-wedding-800 mb-6">Transparência</h1>
          <p className="font-serif text-wedding-600 text-lg max-w-2xl mx-auto">
            Acompanhe o carinho dos nossos convidados em números.
          </p>
        </div>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-16">
          <div className="bg-white p-8 border border-wedding-200 shadow-sm text-center rounded-sm">
            <p className="text-wedding-500 uppercase tracking-widest text-sm font-bold mb-2">Total de Presentes Recebidos</p>
            <p className="font-serif text-6xl text-wedding-800">{totalGifts}</p>
          </div>
          <div className="bg-white p-8 border border-wedding-200 shadow-sm text-center rounded-sm">
             {/* Note: In a real scenario, you might hide the total value or make it optional */}
            <p className="text-wedding-500 uppercase tracking-widest text-sm font-bold mb-2">Valor Total Arrecadado (Estimado)</p>
            <p className="font-serif text-6xl text-wedding-800">R$ {totalValue.toLocaleString('pt-BR')}</p>
          </div>
        </div>

        {/* Chart Section */}
        {totalGifts > 0 ? (
          <div className="bg-white p-8 border border-wedding-200 shadow-sm rounded-sm mb-16">
            <h3 className="font-serif text-2xl text-wedding-800 mb-8 text-center">Presentes Mais Populares</h3>
            <div className="h-80 w-full">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                  <XAxis dataKey="name" stroke="#7d5e4a" fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke="#7d5e4a" fontSize={12} tickLine={false} axisLine={false} allowDecimals={false} />
                  <Tooltip 
                    cursor={{fill: '#f2efe9'}}
                    contentStyle={{ backgroundColor: '#fff', borderColor: '#d5c8b5', fontFamily: 'serif' }}
                  />
                  <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                    {chartData.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill="#b08d71" />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        ) : (
          <div className="text-center py-12 text-wedding-400 italic">
            Nenhum presente recebido ainda. Seja o primeiro!
          </div>
        )}

        {/* Recent Activity List (Anonymized) */}
        <div className="bg-white border border-wedding-200 shadow-sm rounded-sm">
          <div className="p-6 border-b border-wedding-100">
             <h3 className="font-serif text-xl text-wedding-800">Lista de Itens (Status)</h3>
          </div>
          <div className="divide-y divide-wedding-100">
            {gifts.map((gift) => (
              <div key={gift.id} className="p-4 flex justify-between items-center hover:bg-wedding-50 transition">
                <div className="flex items-center gap-4">
                  <img src={gift.imageUrl} alt={gift.name} className="w-12 h-12 object-cover rounded-sm" />
                  <div>
                    <p className="font-medium text-wedding-800">{gift.name}</p>
                    <p className="text-xs text-wedding-500">R$ {gift.price}</p>
                  </div>
                </div>
                <div className="text-right">
                  <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${gift.purchasedCount > 0 ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-800'}`}>
                    {gift.purchasedCount} comprados
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Trash2, Plus, Edit2, Wand2, Loader2, Save } from 'lucide-react';
import { generatePageContent } from '../services/geminiService';
import { Gift, Page } from '../types';

export const AdminPage: React.FC = () => {
  const { settings, updateSettings, gifts, addGift, removeGift, pages, addPage, removePage, resetStore } = useStore();
  const [activeTab, setActiveTab] = useState<'general' | 'gifts' | 'pages'>('general');
  const [apiKey, setApiKey] = useState(process.env.API_KEY || '');

  // States for Gift Form
  const [newGift, setNewGift] = useState<Partial<Gift>>({ name: '', price: 0, description: '', imageUrl: 'https://picsum.photos/400/300' });

  // States for AI Page Gen
  const [aiTopic, setAiTopic] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [generationError, setGenerationError] = useState<string | null>(null);

  const handleGiftSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newGift.name && newGift.price) {
      addGift({
        name: newGift.name,
        price: Number(newGift.price),
        description: newGift.description || '',
        imageUrl: newGift.imageUrl || 'https://picsum.photos/400/300',
      });
      setNewGift({ name: '', price: 0, description: '', imageUrl: 'https://picsum.photos/400/300' });
    }
  };

  const handleGeneratePage = async () => {
    if (!apiKey) {
      alert("Por favor, insira uma API Key do Google Gemini válida.");
      return;
    }
    if (!aiTopic) return;

    setIsGenerating(true);
    setGenerationError(null);
    try {
      const generatedPage = await generatePageContent(aiTopic, pages, apiKey);
      // Ensure unique slug
      let slug = generatedPage.slug;
      if (!slug.startsWith('/')) slug = '/' + slug;
      if (pages.some(p => p.slug === slug)) {
         slug = slug + '-' + Date.now();
      }
      generatedPage.slug = slug;

      addPage(generatedPage);
      setAiTopic('');
      alert("Página gerada com sucesso!");
    } catch (err: any) {
      setGenerationError(err.message || "Falha ao gerar página");
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-wedding-50 py-12 px-4 animate-fade-in">
      <div className="max-w-6xl mx-auto bg-white rounded-lg shadow-xl overflow-hidden border border-wedding-200">

        {/* Header */}
        <div className="bg-wedding-800 text-white p-6 flex justify-between items-center">
          <h1 className="font-serif text-3xl">Painel Administrativo</h1>
          <button onClick={() => { if(confirm('Resetar tudo para o padrão?')) resetStore() }} className="text-xs bg-red-500 hover:bg-red-600 px-3 py-1 rounded">Resetar App</button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-wedding-200">
          <button 
            onClick={() => setActiveTab('general')}
            className={`flex-1 py-4 font-serif text-lg transition-colors ${activeTab === 'general' ? 'bg-wedding-50 text-wedding-800 border-b-2 border-wedding-800' : 'text-wedding-400 hover:text-wedding-600'}`}
          >
            Geral & Configurações
          </button>
          <button 
            onClick={() => setActiveTab('gifts')}
            className={`flex-1 py-4 font-serif text-lg transition-colors ${activeTab === 'gifts' ? 'bg-wedding-50 text-wedding-800 border-b-2 border-wedding-800' : 'text-wedding-400 hover:text-wedding-600'}`}
          >
            Lista de Presentes
          </button>
          <button 
            onClick={() => setActiveTab('pages')}
            className={`flex-1 py-4 font-serif text-lg transition-colors ${activeTab === 'pages' ? 'bg-wedding-50 text-wedding-800 border-b-2 border-wedding-800' : 'text-wedding-400 hover:text-wedding-600'}`}
          >
            Páginas & AI
          </button>
        </div>

        <div className="p-8">

          {/* GENERAL SETTINGS */}
          {activeTab === 'general' && (
            <div className="space-y-6 max-w-2xl mx-auto">
              <h2 className="text-2xl font-serif text-wedding-800 mb-6">Informações do Casamento</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-bold text-wedding-700 mb-2">Nome dos Noivos</label>
                  <input 
                    type="text" 
                    value={settings.coupleName}
                    onChange={(e) => updateSettings({ coupleName: e.target.value })}
                    className="w-full p-2 border border-wedding-300 rounded focus:ring-wedding-500 focus:border-wedding-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-bold text-wedding-700 mb-2">Data</label>
                  <input 
                    type="text" 
                    value={settings.weddingDate}
                    onChange={(e) => updateSettings({ weddingDate: e.target.value })}
                    className="w-full p-2 border border-wedding-300 rounded focus:ring-wedding-500 focus:border-wedding-500"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="block text-sm font-bold text-wedding-700 mb-2">Local</label>
                  <input 
                    type="text" 
