                 <p className="text-xs text-wedding-500 mt-1">Essa chave é usada apenas nesta sessão para a funcionalidade de IA.</p>
              </div>
            </div>
          )}

          {/* GIFTS MANAGEMENT */}
          {activeTab === 'gifts' && (
