import React, { useEffect, useState } from 'react';
import { Heart } from 'lucide-react';

interface LoadingScreenProps {
  isVisible: boolean;
  title: string;
  subtitle: string;
}

export const LoadingScreen: React.FC<LoadingScreenProps> = ({ isVisible, title, subtitle }) => {
  const [shouldRender, setShouldRender] = useState(true);

  useEffect(() => {
    if (!isVisible) {
      // Wait for transition to finish before unmounting
      const timer = setTimeout(() => setShouldRender(false), 1000); 
      return () => clearTimeout(timer);
    } else {
      setShouldRender(true);
    }
  }, [isVisible]);

  if (!shouldRender) return null;

  return (
    <div 
      className={`fixed inset-0 z-[100] flex flex-col items-center justify-center bg-wedding-50 transition-all duration-1000 ease-in-out ${
        isVisible ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'
      }`}
    >
      <div className="text-center animate-fade-in-up">
        {/* Heart Pulse Animation */}
        <div className="mb-6 flex justify-center">
          <div className="relative">
            <Heart size={48} className="text-wedding-400 animate-pulse" fill="#c2ab91" />
            <div className="absolute inset-0 bg-wedding-400 blur-xl opacity-20 animate-pulse"></div>
          </div>
        </div>

        <h1 className="font-script text-5xl md:text-7xl text-wedding-800 mb-4 tracking-wider">
          {title}
        </h1>

        <p className="font-serif text-wedding-600 uppercase tracking-[0.3em] text-xs md:text-sm animate-pulse">
          {subtitle}
        </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import { StoreProvider, useStore } from './store';
import { Layout } from './components/Layout';
import { DynamicPage } from './pages/Home';
import { GiftsPage } from './pages/Gifts';
import { TransparencyPage } from './pages/Transparency';
import { AdminPage } from './pages/Admin';
import { LoginPage } from './pages/Login';
import { LoadingScreen } from './components/LoadingScreen';

// Wrapper component to access Store Context
const AppContent: React.FC = () => {
  const { settings } = useStore();
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Force loading screen for at least 2 seconds to mask API load / initial render glitches
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2000);

    return () => clearTimeout(timer);
  }, []);

  return (
    <>
      <LoadingScreen 
        isVisible={isLoading} 
        title={settings.loadingTitle || "Jéssica & Felipe"} 
        subtitle={settings.loadingSubtitle || "Carregando..."} 
      />

      <Router>
        <Layout>
          <Routes>
            {/* System Routes */}
            <Route path="/login" element={<LoginPage />} />
            <Route path="/gifts" element={<GiftsPage />} />
            <Route path="/transparency" element={<TransparencyPage />} />

            {/* Protected Admin Route */}
            <Route path="/admin" element={<AdminPage />} />

            {/* Dynamic Routes (Home + Generated Pages) */}
            <Route path="/" element={<DynamicPage />} />
            <Route path="/:slug" element={<DynamicPage />} />
          </Routes>
        </Layout>
      </Router>
    </>
  );
};

const App: React.FC = () => {
  return (
    <StoreProvider>
      <AppContent />
    </StoreProvider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useStore } from '../store';
