import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, AppSettings, Gift, Page, GuestMessage, INITIAL_SETTINGS, INITIAL_GIFTS, INITIAL_PAGES } from './types';
import { db, storage } from './firebaseConfig';
import { 
  collection, 
  doc, 
  onSnapshot, 
  updateDoc, 
  setDoc, 
  addDoc, 
  deleteDoc, 
  query,
  orderBy
} from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';

interface StoreContextType extends AppState {
  isAuthenticated: boolean;
  login: (password: string) => boolean;
  logout: () => void;
  updateSettings: (settings: Partial<AppSettings>) => void;
  addGift: (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => void;
  updateGift: (id: string, gift: Partial<Gift>) => void;
  removeGift: (id: string) => void;

  // New Actions
  markGiftAsPending: (giftId: string, buyerName: string) => Promise<void>;
  confirmGiftPayment: (giftId: string) => Promise<void>;

  addPage: (page: Page) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  removePage: (id: string) => void;

  // Messages Actions
  addMessage: (author: string, type: 'audio' | 'video', blob: Blob, giftId?: string) => Promise<void>;
  deleteMessage: (id: string) => Promise<void>;

  resetStore: () => void;
  loading: boolean;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [settings, setSettings] = useState<AppSettings>(INITIAL_SETTINGS);
  const [gifts, setGifts] = useState<Gift[]>([]);
  const [pages, setPages] = useState<Page[]>([]);
  const [messages, setMessages] = useState<GuestMessage[]>([]);

  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  // 1. Sync Settings
  useEffect(() => {
    const unsub = onSnapshot(doc(db, "wedding_site", "settings"), (docSnap) => {
      if (docSnap.exists()) {
        setSettings(docSnap.data() as AppSettings);
      } else {
        setDoc(doc(db, "wedding_site", "settings"), INITIAL_SETTINGS).catch(console.error);
        setSettings(INITIAL_SETTINGS);
      }
      setLoading(false);
    });
    return () => unsub();
  }, []);

  // 2. Sync Gifts
  useEffect(() => {
    const q = query(collection(db, "gifts")); 
    const unsub = onSnapshot(q, (snapshot) => {
      if (snapshot.empty && !loading) { 
         // Only create defaults if empty AND NOT during initial load potentially
         // To be safe, we just check if it's empty
         // (Skipping re-creation logic here to avoid loop if user deleted everything intentionally, 
         // but for first run it's fine if handled carefully)
      } 

      const loadedGifts = snapshot.docs.map(doc => ({
           id: doc.id,
           status: 'available', // default for migration
           ...doc.data()
      })) as Gift[];

      // Sort: Available first, then Pending, then Confirmed
      loadedGifts.sort((a, b) => {
          const statusOrder = { 'available': 0, 'pending': 1, 'confirmed': 2 };
          return statusOrder[a.status] - statusOrder[b.status];
      });

      setGifts(loadedGifts);
    });
    return () => unsub();
  }, [loading]);

  // 3. Sync Pages
  useEffect(() => {
    const unsub = onSnapshot(collection(db, "pages"), (snapshot) => {
      if (snapshot.empty) {
         INITIAL_PAGES.forEach(p => {
            setDoc(doc(db, "pages", p.id), p).catch(console.error);
         });
      } else {
        const loadedPages = snapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        })) as Page[];

        const sortedPages = loadedPages.sort((a, b) => {
          if (a.id === 'home') return -1;
          if (b.id === 'home') return 1;
          return 0;
        });
        setPages(sortedPages);
      }
    });
    return () => unsub();
  }, []);

  // 4. Sync Messages
  useEffect(() => {
      const q = query(collection(db, "messages"), orderBy("createdAt", "desc"));
      const unsub = onSnapshot(q, (snapshot) => {
          const msgs = snapshot.docs.map(doc => ({
              id: doc.id,
              ...doc.data()
          })) as GuestMessage[];
          setMessages(msgs);
      });
      return () => unsub();
  }, []);

  // --- ACTIONS ---

  const login = (password: string) => {
    const currentPass = settings?.adminPassword || INITIAL_SETTINGS.adminPassword;
    if (password === currentPass) {
      setIsAuthenticated(true);
      return true;
    }
    return false;
  };

  const logout = () => setIsAuthenticated(false);

  const updateSettings = async (newSettings: Partial<AppSettings>) => {
    setSettings(prev => ({ ...prev, ...newSettings }));
    try {
      await updateDoc(doc(db, "wedding_site", "settings"), newSettings);
    } catch (error) {
      console.error("Erro ao salvar settings:", error);
    }
  };

  const addGift = async (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => {
    await addDoc(collection(db, "gifts"), {
        ...gift,
        purchasedCount: 0,
        status: 'available'
    });
  };

  const updateGift = async (id: string, updatedGift: Partial<Gift>) => {
    await updateDoc(doc(db, "gifts", id), updatedGift);
  };

  const removeGift = async (id: string) => {
    await deleteDoc(doc(db, "gifts", id));
  };

  const markGiftAsPending = async (giftId: string, buyerName: string) => {
      await updateDoc(doc(db, "gifts", giftId), {
          status: 'pending',
          buyerName: buyerName
      });
  };

  const confirmGiftPayment = async (giftId: string) => {
      const gift = gifts.find(g => g.id === giftId);
      if (gift) {
          await updateDoc(doc(db, "gifts", giftId), {
              status: 'confirmed',
              purchasedCount: gift.purchasedCount + 1
          });
      }
  };

  const addMessage = async (author: string, type: 'audio' | 'video', blob: Blob, giftId?: string) => {
      // 1. Upload to Storage
      const filename = `${Date.now()}-${type === 'audio' ? 'audio.webm' : 'video.webm'}`;
      const storageRef = ref(storage, `messages/${filename}`);

      const snapshot = await uploadBytes(storageRef, blob);
      const downloadURL = await getDownloadURL(snapshot.ref);

      // 2. Save Metadata to Firestore
      const newMessage: Omit<GuestMessage, 'id'> = {
          author,
          type,
          url: downloadURL,
          createdAt: new Date().toISOString(),
          giftId
      };

      await addDoc(collection(db, "messages"), newMessage);
  };

  const deleteMessage = async (id: string) => {
      await deleteDoc(doc(db, "messages", id));
      // Note: In production we should also delete the file from Storage to save space
  };

  const addPage = async (page: Page) => {
    const docId = page.id || crypto.randomUUID();
    await setDoc(doc(db, "pages", docId), { ...page, id: docId });
  };

  const updatePage = async (id: string, updatedPage: Partial<Page>) => {
    await updateDoc(doc(db, "pages", id), updatedPage);
  };

  const removePage = async (id: string) => {
    await deleteDoc(doc(db, "pages", id));
  };

  const resetStore = async () => {
    if (!window.confirm("Isso apagará TODOS os dados?")) return;
    setLoading(true);
    await setDoc(doc(db, "wedding_site", "settings"), INITIAL_SETTINGS);
    for (const g of gifts) await deleteDoc(doc(db, "gifts", g.id));
    for (const p of pages) await deleteDoc(doc(db, "pages", p.id));
    setIsAuthenticated(false);
    setLoading(false);
    alert("Site resetado.");
  };

  return (
    <StoreContext.Provider value={{
      settings,
      gifts,
      pages,
      messages,
      isAuthenticated,
      login,
      logout,
      updateSettings,
      addGift,
      updateGift,
      removeGift,
      markGiftAsPending,
      confirmGiftPayment,
      addMessage,
      deleteMessage,
      addPage,
      updatePage,
      removePage,
      resetStore,
      loading
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { Video, Mic, StopCircle, Play, Trash2, Camera } from 'lucide-react';

interface MediaRecorderProps {
  onRecordingComplete: (blob: Blob, type: 'audio' | 'video') => void;
}

export const MediaRecorder: React.FC<MediaRecorderProps> = ({ onRecordingComplete }) => {
  const [mode, setMode] = useState<'audio' | 'video' | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [mediaBlob, setMediaBlob] = useState<Blob | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const chunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async (selectedMode: 'audio' | 'video') => {
    try {
      const constraints = selectedMode === 'video' 
        ? { video: true, audio: true } 
        : { audio: true };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current && selectedMode === 'video') {
        videoRef.current.srcObject = stream;
      }

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const type = selectedMode === 'video' ? 'video/webm' : 'audio/webm';
        const blob = new Blob(chunksRef.current, { type });
        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);
        setMediaBlob(blob);
        onRecordingComplete(blob, selectedMode);

        // Stop all tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
      setMode(selectedMode);
    } catch (err) {
      console.error("Error accessing media devices:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const reset = () => {
    setPreviewUrl(null);
    setMediaBlob(null);
    setMode(null);
    setIsRecording(false);
  };

  if (previewUrl && mediaBlob) {
    return (
      <div className="w-full mt-4 bg-gray-50 p-4 rounded border border-gray-200">
        <p className="text-sm font-bold text-gray-700 mb-2">Mensagem gravada com sucesso!</p>
        <div className="flex justify-center mb-4">
          {mode === 'video' ? (
            <video src={previewUrl} controls className="w-full max-h-48 rounded bg-black" />
          ) : (
            <audio src={previewUrl} controls className="w-full" />
          )}
        </div>
        <button 
          onClick={reset}
          className="text-red-500 text-sm flex items-center justify-center gap-1 hover:underline w-full"
        >
          <Trash2 size={14} /> Gravar novamente
        </button>
      </div>
    );
  }

  return (
    <div className="w-full mt-4">
      <p className="text-sm text-wedding-600 mb-3 font-medium">Deixe um recado carinhoso (opcional):</p>

      {isRecording ? (
        <div className="flex flex-col items-center gap-4 bg-red-50 p-6 rounded border border-red-100 animate-pulse">
          {mode === 'video' && (
            <video ref={videoRef} autoPlay muted className="w-full h-48 object-cover rounded bg-black transform scale-x-[-1]" />
          )}
          <div className="flex items-center gap-2 text-red-600 font-bold">
            <span className="w-3 h-3 bg-red-600 rounded-full animate-ping"></span>
            Gravando {mode === 'video' ? 'Vídeo' : 'Áudio'}...
          </div>
          <button 
            onClick={stopRecording}
            className="bg-red-600 text-white px-6 py-2 rounded-full hover:bg-red-700 transition flex items-center gap-2"
          >
            <StopCircle size={20} /> Parar Gravação
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => startRecording('video')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Camera size={24} />
            <span className="text-sm font-bold">Gravar Vídeo</span>
          </button>
          <button 
            onClick={() => startRecording('audio')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Mic size={24} />
            <span className="text-sm font-bold">Gravar Áudio</span>
          </button>
        </div>
