import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, AppSettings, Gift, Page, Message, INITIAL_SETTINGS, INITIAL_GIFTS, INITIAL_PAGES } from './types';

interface StoreContextType extends AppState {
  isAuthenticated: boolean;
  login: (password: string) => boolean;
  logout: () => void;
  updateSettings: (settings: Partial<AppSettings>) => void;
  addGift: (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => void;
  updateGift: (id: string, gift: Partial<Gift>) => void;
  removeGift: (id: string) => void;

  // New/Updated Actions
  markGiftAsPending: (id: string, buyerName: string) => void;
  confirmGiftPayment: (id: string) => void;

  addPage: (page: Page) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  removePage: (id: string) => void;

  // Message Actions
  addMessage: (message: Omit<Message, 'id' | 'createdAt'>) => void;
  deleteMessage: (id: string) => void;

  resetStore: () => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // Load from localStorage or use defaults
  const loadState = (): AppState => {
    const stored = localStorage.getItem('wedding_site_store');
    if (stored) {
      const parsed = JSON.parse(stored);

      // MIGRATION LOGIC

      // 1. Settings
      if (!parsed.settings.adminPassword) parsed.settings.adminPassword = INITIAL_SETTINGS.adminPassword;
      if (!parsed.settings.paymentUrl) parsed.settings.paymentUrl = "";
      if (parsed.settings.showMessagesToPublic === undefined) parsed.settings.showMessagesToPublic = false;

      // 2. Pages (Ensure system pages exist)
      const hasMessagesPage = parsed.pages.some((p: Page) => p.id === 'messages-page');
      if (!hasMessagesPage) {
         const msgsPage = INITIAL_PAGES.find(p => p.id === 'messages-page');
         if (msgsPage) parsed.pages.push(msgsPage);
      }

      // 3. Gifts (Ensure status field)
      if (parsed.gifts) {
        parsed.gifts = parsed.gifts.map((g: any) => ({
            ...g,
            status: g.status || 'available',
            buyerName: g.buyerName || ''
        }));
      }

      // 4. Messages (Initialize if missing)
      if (!parsed.messages) {
        parsed.messages = [];
      }

      return parsed;
    }
    return {
      settings: INITIAL_SETTINGS,
      gifts: INITIAL_GIFTS,
      pages: INITIAL_PAGES,
      messages: []
    };
  };

  const [state, setState] = useState<AppState>(loadState);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    try {
        localStorage.setItem('wedding_site_store', JSON.stringify(state));
    } catch (e) {
        console.error("Storage full or error saving state", e);
        alert("Atenção: O armazenamento do navegador está cheio. Alguns vídeos/áudios podem não ser salvos.");
    }
  }, [state]);

  const login = (password: string) => {
    if (password === state.settings.adminPassword) {
      setIsAuthenticated(true);
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
  };

  const updateSettings = (newSettings: Partial<AppSettings>) => {
    setState(prev => ({ ...prev, settings: { ...prev.settings, ...newSettings } }));
  };

  const addGift = (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => {
    const newGift: Gift = {
      ...gift,
      id: crypto.randomUUID(),
      purchasedCount: 0,
      status: 'available'
    };
    setState(prev => ({ ...prev, gifts: [...prev.gifts, newGift] }));
  };

  const updateGift = (id: string, updatedGift: Partial<Gift>) => {
    setState(prev => ({
      ...prev,
      gifts: prev.gifts.map(g => g.id === id ? { ...g, ...updatedGift } : g)
    }));
  };

  const removeGift = (id: string) => {
    setState(prev => ({ ...prev, gifts: prev.gifts.filter(g => g.id !== id) }));
  };

  // User marks as paid -> Pending
  const markGiftAsPending = (id: string, buyerName: string) => {
    setState(prev => ({
      ...prev,
      gifts: prev.gifts.map(g => g.id === id ? { ...g, status: 'pending', buyerName } : g)
    }));
  };

  // Admin confirms payment -> Confirmed (and increments count)
  const confirmGiftPayment = (id: string) => {
    setState(prev => ({
      ...prev,
      gifts: prev.gifts.map(g => g.id === id ? { 
          ...g, 
          status: 'confirmed', 
          purchasedCount: g.purchasedCount + 1 
      } : g)
    }));
  };

  const addPage = (page: Page) => {
    setState(prev => ({ ...prev, pages: [...prev.pages, page] }));
  };

  const updatePage = (id: string, updatedPage: Partial<Page>) => {
    setState(prev => ({
      ...prev,
      pages: prev.pages.map(p => p.id === id ? { ...p, ...updatedPage } : p)
    }));
  };

  const removePage = (id: string) => {
    setState(prev => ({ ...prev, pages: prev.pages.filter(p => p.id !== id) }));
  };

  const addMessage = (message: Omit<Message, 'id' | 'createdAt'>) => {
      const newMessage: Message = {
          ...message,
          id: crypto.randomUUID(),
          createdAt: new Date().toISOString()
      };
      setState(prev => ({ ...prev, messages: [newMessage, ...prev.messages] }));
  };

  const deleteMessage = (id: string) => {
      setState(prev => ({ ...prev, messages: prev.messages.filter(m => m.id !== id) }));
  };

  const resetStore = () => {
    setState({
      settings: INITIAL_SETTINGS,
      gifts: INITIAL_GIFTS,
      pages: INITIAL_PAGES,
      messages: []
    });
    setIsAuthenticated(false);
  };

  return (
    <StoreContext.Provider value={{
      ...state,
      isAuthenticated,
      login,
      logout,
      updateSettings,
      addGift,
      updateGift,
      removeGift,
      markGiftAsPending,
      confirmGiftPayment,
      addPage,
      updatePage,
      removePage,
      addMessage,
      deleteMessage,
      resetStore
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React, { useState, useRef } from 'react';
import { Video, Mic, StopCircle, Play, Trash2, Camera } from 'lucide-react';

interface MediaRecorderProps {
  onRecordingComplete: (base64: string, type: 'audio' | 'video') => void;
}

export const MediaRecorder: React.FC<MediaRecorderProps> = ({ onRecordingComplete }) => {
  const [mode, setMode] = useState<'audio' | 'video' | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [mediaBase64, setMediaBase64] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const chunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async (selectedMode: 'audio' | 'video') => {
    try {
      const constraints = selectedMode === 'video' 
        ? { video: { width: 320, height: 240 }, audio: true } // Low res to save space
        : { audio: true };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current && selectedMode === 'video') {
        videoRef.current.srcObject = stream;
      }

      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const type = selectedMode === 'video' ? 'video/webm' : 'audio/webm';
        const blob = new Blob(chunksRef.current, { type });
        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);

        // Convert to Base64
        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onloadend = () => {
            const base64data = reader.result as string;
            setMediaBase64(base64data);
            onRecordingComplete(base64data, selectedMode);
        };

        // Stop all tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
      setMode(selectedMode);
    } catch (err) {
      console.error("Error accessing media devices:", err);
      alert("Não foi possível acessar a câmera ou microfone. Verifique as permissões.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const reset = () => {
    setPreviewUrl(null);
    setMediaBase64(null);
    setMode(null);
    setIsRecording(false);
  };

  if (previewUrl && mediaBase64) {
    return (
      <div className="w-full mt-4 bg-gray-50 p-4 rounded border border-gray-200">
        <p className="text-sm font-bold text-gray-700 mb-2">Mensagem gravada com sucesso!</p>
        <div className="flex justify-center mb-4">
          {mode === 'video' ? (
            <video src={previewUrl} controls className="w-full max-h-48 rounded bg-black" />
          ) : (
            <audio src={previewUrl} controls className="w-full" />
          )}
        </div>
        <button 
          onClick={reset}
          className="text-red-500 text-sm flex items-center justify-center gap-1 hover:underline w-full"
        >
          <Trash2 size={14} /> Gravar novamente
        </button>
      </div>
    );
  }

  return (
    <div className="w-full mt-4">
      <p className="text-sm text-wedding-600 mb-3 font-medium">Deixe um recado carinhoso (opcional):</p>

      {isRecording ? (
        <div className="flex flex-col items-center gap-4 bg-red-50 p-6 rounded border border-red-100 animate-pulse">
          {mode === 'video' && (
            <video ref={videoRef} autoPlay muted className="w-full h-48 object-cover rounded bg-black transform scale-x-[-1]" />
          )}
          <div className="flex items-center gap-2 text-red-600 font-bold">
            <span className="w-3 h-3 bg-red-600 rounded-full animate-ping"></span>
            Gravando {mode === 'video' ? 'Vídeo' : 'Áudio'}...
          </div>
          <button 
            onClick={stopRecording}
            className="bg-red-600 text-white px-6 py-2 rounded-full hover:bg-red-700 transition flex items-center gap-2"
          >
            <StopCircle size={20} /> Parar Gravação
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => startRecording('video')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Camera size={24} />
            <span className="text-sm font-bold">Gravar Vídeo</span>
          </button>
          <button 
            onClick={() => startRecording('audio')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Mic size={24} />
            <span className="text-sm font-bold">Gravar Áudio</span>
          </button>
        </div>
      )}
    </div>
  );
};

