      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const type = selectedMode === 'video' ? mediaRecorder.mimeType || 'video/webm' : 'audio/webm';
        const blob = new Blob(chunksRef.current, { type });
        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);

        // Convert to Base64 (for preview consistency) and pass Blob (for upload)
        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onloadend = () => {
            const base64data = reader.result as string;
            setMediaBase64(base64data);
            onRecordingComplete(base64data, blob, selectedMode);
        };

        // Stop all tracks
        stream.getTracks().forEach(track => track.stop());
      };

      mediaRecorder.start();
      setIsRecording(true);
      setMode(selectedMode);
    } catch (err: any) {
      console.error("Error accessing media devices:", err);
      if (err.name === 'NotAllowedError' || err.name === 'PermissionDeniedError') {
        alert("Permissão negada. Por favor, permita o acesso à câmera e microfone nas configurações do navegador para gravar sua mensagem.");
      } else if (err.name === 'NotFoundError') {
        alert("Nenhum dispositivo de câmera ou microfone foi encontrado.");
      } else {
        alert("Não foi possível acessar a câmera ou microfone: " + (err.message || "Erro desconhecido"));
      }
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const reset = () => {
    setPreviewUrl(null);
    setMediaBase64(null);
    setMode(null);
    setIsRecording(false);
  };

  if (previewUrl && mediaBase64) {
    return (
      <div className="w-full mt-4 bg-gray-50 p-4 rounded border border-gray-200">
        <p className="text-sm font-bold text-gray-700 mb-2">Mensagem gravada com sucesso!</p>
        <div className="flex justify-center mb-4">
          {mode === 'video' ? (
            <video src={previewUrl} controls className="w-full max-h-48 rounded bg-black" />
          ) : (
            <audio src={previewUrl} controls className="w-full" />
          )}
        </div>
        <button 
          onClick={reset}
          className="text-red-500 text-sm flex items-center justify-center gap-1 hover:underline w-full"
        >
          <Trash2 size={14} /> Gravar novamente
        </button>
      </div>
    );
  }

  return (
    <div className="w-full mt-4">
      <p className="text-sm text-wedding-600 mb-3 font-medium">Deixe um recado carinhoso (opcional):</p>

      {isRecording ? (
        <div className="flex flex-col items-center gap-4 bg-red-50 p-6 rounded border border-red-100 animate-pulse">
          {mode === 'video' && (
            <video ref={videoRef} autoPlay muted className="w-full h-48 object-cover rounded bg-black transform scale-x-[-1]" />
          )}
          <div className="flex items-center gap-2 text-red-600 font-bold">
            <span className="w-3 h-3 bg-red-600 rounded-full animate-ping"></span>
            Gravando {mode === 'video' ? 'Vídeo' : 'Áudio'}...
          </div>
          <button 
            onClick={stopRecording}
            className="bg-red-600 text-white px-6 py-2 rounded-full hover:bg-red-700 transition flex items-center gap-2"
          >
            <StopCircle size={20} /> Parar Gravação
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => startRecording('video')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Camera size={24} />
            <span className="text-sm font-bold">Gravar Vídeo</span>
          </button>
          <button 
            onClick={() => startRecording('audio')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Mic size={24} />
            <span className="text-sm font-bold">Gravar Áudio</span>
          </button>
        </div>
      )}
    </div>
  );
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AppState, AppSettings, Gift, Page, Message, INITIAL_SETTINGS, INITIAL_GIFTS, INITIAL_PAGES } from './types';
import { db } from './firebaseConfig';
import { 
  collection, 
  onSnapshot, 
  doc, 
  setDoc, 
  updateDoc, 
  deleteDoc, 
  addDoc,
  getDoc,
  writeBatch
} from 'firebase/firestore';

interface StoreContextType extends AppState {
  isAuthenticated: boolean;
  login: (password: string) => boolean;
  logout: () => void;
  updateSettings: (settings: Partial<AppSettings>) => void;
  addGift: (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => void;
  updateGift: (id: string, gift: Partial<Gift>) => void;
  removeGift: (id: string) => void;

  markGiftAsPending: (id: string, buyerName: string) => void;
  confirmGiftPayment: (id: string) => void;

  addPage: (page: Page) => void;
  updatePage: (id: string, page: Partial<Page>) => void;
  removePage: (id: string) => void;

  addMessage: (message: Omit<Message, 'id' | 'createdAt'>) => void;
  deleteMessage: (id: string) => void;

  resetStore: () => void;
}

const StoreContext = createContext<StoreContextType | undefined>(undefined);

export const StoreProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>({
      settings: INITIAL_SETTINGS,
      gifts: [],
      pages: [],
      messages: []
  });
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [loading, setLoading] = useState(true);

  // --- FIREBASE LISTENERS ---

  useEffect(() => {
    // 1. Settings Listener
    const unsubSettings = onSnapshot(doc(db, "app", "settings"), (docSnap) => {
        if (docSnap.exists()) {
            setState(prev => ({ ...prev, settings: docSnap.data() as AppSettings }));
        } else {
            // First run: Initialize settings in DB
            setDoc(doc(db, "app", "settings"), INITIAL_SETTINGS);
            setState(prev => ({ ...prev, settings: INITIAL_SETTINGS }));
        }
    });

    // 2. Gifts Listener
    const unsubGifts = onSnapshot(collection(db, "gifts"), (snapshot) => {
        const giftsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Gift));
        if (giftsData.length === 0 && loading) {
             // Optional: If empty on first load, seed with initials
             // But we avoid auto-seeding to prevent duplicates if user deleted all.
             // We only seed if we are SURE it's a fresh install.
        }
        setState(prev => ({ ...prev, gifts: giftsData }));
    });

    // 3. Pages Listener
    const unsubPages = onSnapshot(collection(db, "pages"), (snapshot) => {
        const pagesData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Page));
        // Sort pages or ensure system pages?
        // If empty, we might want to seed.
        if (pagesData.length === 0) {
             // Seeding logic could go here, but let's keep it simple for now.
             // Manually checking if pages exist is safer.
        }
        setState(prev => ({ ...prev, pages: pagesData }));
    });

    // 4. Messages Listener
    const unsubMessages = onSnapshot(collection(db, "messages"), (snapshot) => {
        const msgsData = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Message));
        // Sort by date desc
        msgsData.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
        setState(prev => ({ ...prev, messages: msgsData }));
    });

    setLoading(false);

    return () => {
        unsubSettings();
        unsubGifts();
        unsubPages();
        unsubMessages();
    };
  }, []);

  // Seed Initial Data check
  useEffect(() => {
     const checkAndSeed = async () => {
         // Check if we have pages
         const pagesSnap = await getDoc(doc(db, "pages", "home")); // Check for a known page
         // Only seed if strictly necessary. For now, rely on Admin Reset to seed.
     }
     checkAndSeed();
  }, []);


  // --- ACTIONS ---

  const login = (password: string) => {
    if (password === state.settings.adminPassword) {
      setIsAuthenticated(true);
      return true;
    }
    return false;
  };

  const logout = () => {
    setIsAuthenticated(false);
  };

  const updateSettings = async (newSettings: Partial<AppSettings>) => {
    const updated = { ...state.settings, ...newSettings };
    await setDoc(doc(db, "app", "settings"), updated);
  };

  // GIFTS
  const addGift = async (gift: Omit<Gift, 'id' | 'purchasedCount' | 'status'>) => {
    const newGift = {
      ...gift,
      purchasedCount: 0,
      status: 'available'
    };
    await addDoc(collection(db, "gifts"), newGift);
  };

  const updateGift = async (id: string, updatedGift: Partial<Gift>) => {
    await updateDoc(doc(db, "gifts", id), updatedGift);
  };

  const removeGift = async (id: string) => {
    await deleteDoc(doc(db, "gifts", id));
  };

  const markGiftAsPending = async (id: string, buyerName: string) => {
    await updateDoc(doc(db, "gifts", id), {
        status: 'pending',
        buyerName: buyerName
    });
  };

  const confirmGiftPayment = async (id: string) => {
     // We need to increment, easier to just get current state locally since we are sync'd
     const gift = state.gifts.find(g => g.id === id);
     if(gift) {
         await updateDoc(doc(db, "gifts", id), {
             status: 'confirmed',
             purchasedCount: gift.purchasedCount + 1
         });
     }
  };

  // PAGES
  const addPage = async (page: Page) => {
    // Use slug as ID or random? Random is safer for collision, but page ID usage varies.
    // Let's use Random ID provided by firestore, but we passed ID in object.
    // Let's use the ID from the object if it exists (usually random UUID from Admin)
    const { id, ...pageData } = page;
    if (id) {
        await setDoc(doc(db, "pages", id), { id, ...pageData });
    } else {
        await addDoc(collection(db, "pages"), pageData);
    }
  };

  const updatePage = async (id: string, updatedPage: Partial<Page>) => {
    await updateDoc(doc(db, "pages", id), updatedPage);
  };

  const removePage = async (id: string) => {
    await deleteDoc(doc(db, "pages", id));
  };

  // MESSAGES
  const addMessage = async (message: Omit<Message, 'id' | 'createdAt'>) => {
      const newMessage = {
          ...message,
          createdAt: new Date().toISOString()
      };
      await addDoc(collection(db, "messages"), newMessage);
  };

  const deleteMessage = async (id: string) => {
      await deleteDoc(doc(db, "messages", id));
  };

  const resetStore = async () => {
    // WARNING: This deletes everything in Firestore for this app

    // 1. Reset Settings
    await setDoc(doc(db, "app", "settings"), INITIAL_SETTINGS);

    // 2. Clear Collections and Seed
    const batch = writeBatch(db);

    // Delete existing Gifts (Local view only for simplicity, in real app, need to query all)
    state.gifts.forEach(g => batch.delete(doc(db, "gifts", g.id)));
    // Seed Gifts
    INITIAL_GIFTS.forEach(g => {
        const docRef = doc(collection(db, "gifts"));
        batch.set(docRef, { ...g, id: docRef.id }); // Assign new IDs
    });

    // Pages
    state.pages.forEach(p => batch.delete(doc(db, "pages", p.id)));
    INITIAL_PAGES.forEach(p => {
        // Keep fixed IDs for system pages if possible, or update ID
        const docRef = doc(db, "pages", p.id); 
        batch.set(docRef, p);
    });

    // Messages
    state.messages.forEach(m => batch.delete(doc(db, "messages", m.id)));

    await batch.commit();
    setIsAuthenticated(false);
  };

  return (
    <StoreContext.Provider value={{
      ...state,
      isAuthenticated,
      login,
      logout,
      updateSettings,
      addGift,
      updateGift,
      removeGift,
      markGiftAsPending,
      confirmGiftPayment,
      addPage,
      updatePage,
      removePage,
      addMessage,
      deleteMessage,
      resetStore
    }}>
      {children}
    </StoreContext.Provider>
  );
};

export const useStore = () => {
  const context = useContext(StoreContext);
  if (!context) throw new Error("useStore must be used within StoreProvider");
  return context;
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Modal } from '../components/Modal';
import { QRCodeSVG } from 'qrcode.react';
import { Gift as GiftIcon, Heart, Copy, CheckCircle, CreditCard, ExternalLink, Loader2 } from 'lucide-react';
import { Recorder } from '../components/MediaRecorder';
import { storage } from '../firebaseConfig'; // Import Storage
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';

export const GiftsPage: React.FC = () => {
  const { gifts, settings, markGiftAsPending, addMessage } = useStore();
  const [selectedGift, setSelectedGift] = useState<string | null>(null);

  // States for Purchase Flow
  const [buyerName, setBuyerName] = useState('');

  // Media states
  const [mediaPreview, setMediaPreview] = useState<string | null>(null); // Base64 for instant preview
  const [mediaBlob, setMediaBlob] = useState<Blob | null>(null); // Real file for upload
  const [mediaType, setMediaType] = useState<'audio' | 'video' | null>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState('');
  const [showThankYouModal, setShowThankYouModal] = useState(false);

  // Toast
  const [showToast, setShowToast] = useState(false);

  const handleOpenGift = (giftId: string) => {
    setSelectedGift(giftId);
    setBuyerName('');
    setMediaPreview(null);
    setMediaBlob(null);
    setMediaType(null);
    setUploadProgress('');
  };

  const activeGift = gifts.find(g => g.id === selectedGift);

  const handleCopyPix = () => {
    navigator.clipboard.writeText(settings.pixKey);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 5000);
  };

  const handleSubmit = async () => {
    if (!activeGift) return;

    if (!buyerName.trim()) {
        alert("Por favor, digite seu nome para que os noivos saibam quem enviou!");
        return;
    }

    setIsSubmitting(true);
    setUploadProgress('Processando...');

    try {
        let downloadUrl = '';

        // 1. Upload Media if exists
        if (mediaBlob && mediaType) {
            setUploadProgress('Enviando vídeo/áudio...');
            const extension = mediaType === 'video' ? 'webm' : 'webm'; // Browser recorder usually outputs webm
            const fileName = `messages/${Date.now()}_${buyerName.replace(/\s+/g, '_')}.${extension}`;
            const storageRef = ref(storage, fileName);

            await uploadBytes(storageRef, mediaBlob);
            downloadUrl = await getDownloadURL(storageRef);
            console.log("File uploaded:", downloadUrl);
        }

        // 2. Save Message with URL
        if (downloadUrl || (mediaPreview && !mediaBlob)) {
             // Fallback for audio if logic changes, but we prefer Blob
            addMessage({
                author: buyerName,
                type: mediaType || 'audio',
                content: downloadUrl, // Save the Firebase URL, not Base64
                giftId: activeGift.id
            });
        }

        // 3. Mark Gift as Pending
        markGiftAsPending(activeGift.id, buyerName);

        setUploadProgress('Concluído!');
        setTimeout(() => {
            setIsSubmitting(false);
            setSelectedGift(null);
            alert("Obrigado! Avisamos os noivos do seu presente. O vídeo foi salvo com sucesso!");
        }, 500);

    } catch (error) {
        console.error("Error submitting gift:", error);
        alert("Houve um erro ao salvar o vídeo ou o presente. Tente novamente.");
        setIsSubmitting(false);
    }
  };

  // Helper to get card styles based on status
  const getCardStyle = (status: string) => {
      if (status === 'confirmed') {
          return "border-green-400 bg-green-50 shadow-green-100";
      }
      if (status === 'pending') {
          return "border-yellow-300 bg-yellow-50 shadow-sm";
      }
      return "border-wedding-100 bg-white hover:shadow-xl";
  };

  return (
    <div className="min-h-screen bg-wedding-50 py-12 animate-fade-in relative">

      {/* Toast Notification */}
      <div className={`fixed top-24 right-4 z-[60] max-w-sm w-full bg-white border border-wedding-300 shadow-xl rounded-lg p-4 transform transition-all duration-500 ease-in-out ${showToast ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}>
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0 text-green-500 mt-0.5">
            <CheckCircle size={20} />
          </div>
          <div>
            <p className="text-sm font-medium text-wedding-900 mb-1">Sucesso!</p>
            <p className="text-sm text-wedding-600 leading-relaxed">
              Chave pix copiada!
            </p>
          </div>
        </div>
      </div>

      {/* Header */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-16 text-center">
        <h1 className="font-script text-6xl text-wedding-800 mb-6">Lista de Presentes</h1>
        <p className="font-serif text-wedding-600 text-lg max-w-2xl mx-auto">
          Sua presença é o nosso maior presente. Mas se quiserem nos agraciar com um mimo para o início da nossa vida a dois, ficaremos muito felizes!
        </p>
      </div>

      {/* Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {gifts.map((gift) => {
            const isConfirmed = gift.status === 'confirmed';

            return (
                <div key={gift.id} className={`rounded-sm shadow-md overflow-hidden transition-all duration-300 border group flex flex-col h-full ${getCardStyle(gift.status)}`}>
                <div className="h-64 overflow-hidden relative flex-shrink-0">
                    <img 
                    src={gift.imageUrl} 
                    alt={gift.name} 
                    className={`w-full h-full object-cover transition-transform duration-700 ${isConfirmed ? 'grayscale opacity-70' : 'group-hover:scale-110'}`} 
                    />
                    <div className={`absolute top-0 right-0 px-3 py-1 m-2 text-sm font-bold shadow-sm ${isConfirmed ? 'bg-green-600 text-white' : 'bg-wedding-500 text-white'}`}>
                    R$ {gift.price.toFixed(2)}
                    </div>
                </div>
                <div className="p-6 text-center flex flex-col flex-grow">
                    <div className="h-14 mb-2 flex items-center justify-center w-full">
                        <h3 className="font-serif text-xl text-wedding-800 line-clamp-2 leading-tight px-2">{gift.name}</h3>
                    </div>
                    <p className="text-wedding-600 text-sm mb-6 line-clamp-3 px-2">{gift.description}</p>
                    <div className="mt-auto w-full">
                        <button
                        onClick={() => isConfirmed ? setShowThankYouModal(true) : handleOpenGift(gift.id)}
                        disabled={isConfirmed && false} 
                        className={`w-full font-serif py-3 px-6 transition-colors flex items-center justify-center gap-2 uppercase tracking-widest text-xs
                            ${isConfirmed 
                                ? 'bg-green-600 text-white cursor-default' 
                                : 'bg-wedding-800 hover:bg-wedding-600 text-white'
                            }`}
                        >
                        {isConfirmed ? (
                            <><CheckCircle size={16} /> AGRADECEMOS O PRESENTE! ❤️</>
                        ) : (
                            <><GiftIcon size={16} /> Faça os noivos felizes</>
                        )}
                        </button>
                    </div>
                </div>
                </div>
            );
          })}
        </div>
      </div>

      {/* Thank You Modal */}
      <Modal
