import React, { useState, useRef } from 'react';
import { Video, Mic, StopCircle, Play, Trash2, Camera } from 'lucide-react';

interface MediaRecorderProps {
  onRecordingComplete: (base64: string, blob: Blob, type: 'audio' | 'video') => void;
}

export const Recorder: React.FC<MediaRecorderProps> = ({ onRecordingComplete }) => {
  const [mode, setMode] = useState<'audio' | 'video' | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [mediaBase64, setMediaBase64] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const chunksRef = useRef<Blob[]>([]);
  const streamRef = useRef<MediaStream | null>(null);

  const startRecording = async (selectedMode: 'audio' | 'video') => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      alert("Seu navegador não suporta gravação de mídia ou a conexão não é segura (HTTPS necessária).");
      return;
    }

    try {
      const constraints = selectedMode === 'video' 
        ? { video: { width: 480, height: 360 }, audio: true }
        : { audio: true };

      const stream = await navigator.mediaDevices.getUserMedia(constraints);
      streamRef.current = stream;

      if (videoRef.current && selectedMode === 'video') {
        videoRef.current.srcObject = stream;
      }

      // Detecta suporte a mimeTypes
      let options = {};
      if (MediaRecorder.isTypeSupported('video/webm;codecs=vp9')) {
        options = { mimeType: 'video/webm;codecs=vp9' };
      } else if (MediaRecorder.isTypeSupported('video/webm')) {
        options = { mimeType: 'video/webm' };
      } else if (MediaRecorder.isTypeSupported('video/mp4')) {
        options = { mimeType: 'video/mp4' };
      }

      const mediaRecorder = new MediaRecorder(stream, options);
      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        if (e.data && e.data.size > 0) {
          chunksRef.current.push(e.data);
        }
      };

      mediaRecorder.onstop = () => {
        const type = selectedMode === 'video' ? mediaRecorder.mimeType || 'video/webm' : 'audio/webm';
        const blob = new Blob(chunksRef.current, { type });

        console.log(`Gravação finalizada. Tamanho: ${blob.size} bytes. Tipo: ${type}`);

        if (blob.size === 0) {
            alert("Erro: A gravação ficou vazia. Tente novamente.");
            return;
        }

        const url = URL.createObjectURL(blob);
        setPreviewUrl(url);

        const reader = new FileReader();
        reader.readAsDataURL(blob);
        reader.onloadend = () => {
            const base64data = reader.result as string;
            setMediaBase64(base64data);
            onRecordingComplete(base64data, blob, selectedMode);
        };

        // Stop all tracks cleanly
        stream.getTracks().forEach(track => track.stop());
      };

      // Importante: start(1000) força a criação de chunks a cada 1s, garantindo dados no onstop
      mediaRecorder.start(1000);
      setIsRecording(true);
      setMode(selectedMode);
    } catch (err: any) {
      console.error("Error accessing media devices:", err);
      alert("Erro ao acessar câmera/microfone: " + (err.message || "Verifique as permissões do navegador."));
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const reset = () => {
    setPreviewUrl(null);
    setMediaBase64(null);
    setMode(null);
    setIsRecording(false);
  };

  if (previewUrl && mediaBase64) {
    return (
      <div className="w-full mt-4 bg-gray-50 p-4 rounded border border-gray-200">
        <p className="text-sm font-bold text-gray-700 mb-2">Mensagem gravada com sucesso!</p>
        <div className="flex justify-center mb-4">
          {mode === 'video' ? (
            <video src={previewUrl} controls className="w-full max-h-48 rounded bg-black" />
          ) : (
            <audio src={previewUrl} controls className="w-full" />
          )}
        </div>
        <button 
          onClick={reset}
          className="text-red-500 text-sm flex items-center justify-center gap-1 hover:underline w-full"
        >
          <Trash2 size={14} /> Gravar novamente
        </button>
      </div>
    );
  }

  return (
    <div className="w-full mt-4">
      <p className="text-sm text-wedding-600 mb-3 font-medium">Deixe um recado carinhoso (opcional):</p>

      {isRecording ? (
        <div className="flex flex-col items-center gap-4 bg-red-50 p-6 rounded border border-red-100 animate-pulse">
          {mode === 'video' && (
            <video ref={videoRef} autoPlay muted className="w-full h-48 object-cover rounded bg-black transform scale-x-[-1]" />
          )}
          <div className="flex items-center gap-2 text-red-600 font-bold">
            <span className="w-3 h-3 bg-red-600 rounded-full animate-ping"></span>
            Gravando {mode === 'video' ? 'Vídeo' : 'Áudio'}...
          </div>
          <button 
            onClick={stopRecording}
            className="bg-red-600 text-white px-6 py-2 rounded-full hover:bg-red-700 transition flex items-center gap-2"
          >
            <StopCircle size={20} /> Parar Gravação
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          <button 
            onClick={() => startRecording('video')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Camera size={24} />
            <span className="text-sm font-bold">Gravar Vídeo</span>
          </button>
          <button 
            onClick={() => startRecording('audio')}
            className="flex flex-col items-center justify-center p-4 border border-wedding-300 rounded hover:bg-wedding-100 transition gap-2 text-wedding-700"
          >
            <Mic size={24} />
            <span className="text-sm font-bold">Gravar Áudio</span>
          </button>
        </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useStore } from '../store';
import { Modal } from '../components/Modal';
import { QRCodeSVG } from 'qrcode.react';
import { Gift as GiftIcon, Heart, Copy, CheckCircle, CreditCard, ExternalLink, Loader2 } from 'lucide-react';
import { Recorder } from '../components/MediaRecorder';
import { storage } from '../firebaseConfig'; // Import Storage
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';

export const GiftsPage: React.FC = () => {
  const { gifts, settings, markGiftAsPending, addMessage } = useStore();
  const [selectedGift, setSelectedGift] = useState<string | null>(null);

  // States for Purchase Flow
  const [buyerName, setBuyerName] = useState('');

  // Media states
  const [mediaPreview, setMediaPreview] = useState<string | null>(null); // Base64 for instant preview
  const [mediaBlob, setMediaBlob] = useState<Blob | null>(null); // Real file for upload
  const [mediaType, setMediaType] = useState<'audio' | 'video' | null>(null);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [uploadProgress, setUploadProgress] = useState('');
  const [showThankYouModal, setShowThankYouModal] = useState(false);

  // Toast
  const [showToast, setShowToast] = useState(false);

  const handleOpenGift = (giftId: string) => {
    setSelectedGift(giftId);
    setBuyerName('');
    setMediaPreview(null);
    setMediaBlob(null);
    setMediaType(null);
    setUploadProgress('');
  };

  const activeGift = gifts.find(g => g.id === selectedGift);

  const handleCopyPix = () => {
    navigator.clipboard.writeText(settings.pixKey);
    setShowToast(true);
    setTimeout(() => setShowToast(false), 5000);
  };

  const handleSubmit = async () => {
    if (!activeGift) return;

    if (!buyerName.trim()) {
        alert("Por favor, digite seu nome para que os noivos saibam quem enviou!");
        return;
    }

    setIsSubmitting(true);
    setUploadProgress('Processando...');

    try {
        let downloadUrl = '';

        // 1. Upload Media if exists
        if (mediaBlob && mediaType) {

            if (mediaBlob.size === 0) {
                 throw new Error("O arquivo de vídeo está vazio (0 bytes). Tente gravar novamente.");
            }

            setUploadProgress('Enviando vídeo/áudio...');
            const extension = mediaType === 'video' ? 'webm' : 'webm'; 
            // Sanitize filename
            const safeName = buyerName.replace(/[^a-z0-9]/gi, '_').toLowerCase();
            const fileName = `messages/${Date.now()}_${safeName}.${extension}`;
            const storageRef = ref(storage, fileName);

            // Upload com timeout simulado (Firebase não tem timeout nativo fácil)
            // Se demorar mais de 60s, a gente assume erro de rede/permissão
            const uploadPromise = uploadBytes(storageRef, mediaBlob);

            // Race a timeout
            const timeoutPromise = new Promise((_, reject) => 
                setTimeout(() => reject(new Error("O envio demorou muito. Verifique sua conexão ou se as permissões do Firebase estão configuradas.")), 60000)
            );

            await Promise.race([uploadPromise, timeoutPromise]);

            downloadUrl = await getDownloadURL(storageRef);
            console.log("File uploaded successfully:", downloadUrl);
        }

        // 2. Save Message with URL
        if (downloadUrl || (mediaPreview && !mediaBlob)) {
             setUploadProgress('Salvando recado...');
             addMessage({
                author: buyerName,
                type: mediaType || 'audio',
                content: downloadUrl, 
                giftId: activeGift.id
            });
        }

        // 3. Mark Gift as Pending
        setUploadProgress('Finalizando...');
        markGiftAsPending(activeGift.id, buyerName);

        setTimeout(() => {
            setIsSubmitting(false);
            setSelectedGift(null);
            alert("Obrigado! Avisamos os noivos do seu presente. O vídeo foi salvo com sucesso!");
        }, 500);

    } catch (error: any) {
        console.error("Error submitting gift:", error);

        let msg = "Houve um erro ao salvar.";
        if (error.code === 'storage/unauthorized') {
            msg = "Erro de Permissão: O Firebase Storage bloqueou o envio. Verifique as 'Rules' no console do Firebase.";
        } else if (error.message) {
            msg = `Erro: ${error.message}`;
        }

        alert(msg);
        setIsSubmitting(false);
        setUploadProgress('');
    }
  };

  const getCardStyle = (status: string) => {
      if (status === 'confirmed') {
          return "border-green-400 bg-green-50 shadow-green-100";
      }
      if (status === 'pending') {
          return "border-yellow-300 bg-yellow-50 shadow-sm";
      }
      return "border-wedding-100 bg-white hover:shadow-xl";
  };

  return (
    <div className="min-h-screen bg-wedding-50 py-12 animate-fade-in relative">

      {/* Toast Notification */}
      <div className={`fixed top-24 right-4 z-[60] max-w-sm w-full bg-white border border-wedding-300 shadow-xl rounded-lg p-4 transform transition-all duration-500 ease-in-out ${showToast ? 'translate-x-0 opacity-100' : 'translate-x-full opacity-0 pointer-events-none'}`}>
        <div className="flex items-start gap-3">
          <div className="flex-shrink-0 text-green-500 mt-0.5">
            <CheckCircle size={20} />
          </div>
          <div>
            <p className="text-sm font-medium text-wedding-900 mb-1">Sucesso!</p>
            <p className="text-sm text-wedding-600 leading-relaxed">
              Chave pix copiada!
            </p>
          </div>
        </div>
      </div>

      {/* Header */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mb-16 text-center">
        <h1 className="font-script text-6xl text-wedding-800 mb-6">Lista de Presentes</h1>
        <p className="font-serif text-wedding-600 text-lg max-w-2xl mx-auto">
          Sua presença é o nosso maior presente. Mas se quiserem nos agraciar com um mimo para o início da nossa vida a dois, ficaremos muito felizes!
        </p>
      </div>

      {/* Grid */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {gifts.map((gift) => {
            const isConfirmed = gift.status === 'confirmed';

            return (
                <div key={gift.id} className={`rounded-sm shadow-md overflow-hidden transition-all duration-300 border group flex flex-col h-full ${getCardStyle(gift.status)}`}>
                <div className="h-64 overflow-hidden relative flex-shrink-0">
                    <img 
                    src={gift.imageUrl} 
                    alt={gift.name} 
                    className={`w-full h-full object-cover transition-transform duration-700 ${isConfirmed ? 'grayscale opacity-70' : 'group-hover:scale-110'}`} 
                    />
                    <div className={`absolute top-0 right-0 px-3 py-1 m-2 text-sm font-bold shadow-sm ${isConfirmed ? 'bg-green-600 text-white' : 'bg-wedding-500 text-white'}`}>
                    R$ {gift.price.toFixed(2)}
                    </div>
                </div>
                <div className="p-6 text-center flex flex-col flex-grow">
                    <div className="h-14 mb-2 flex items-center justify-center w-full">
                        <h3 className="font-serif text-xl text-wedding-800 line-clamp-2 leading-tight px-2">{gift.name}</h3>
                    </div>
                    <p className="text-wedding-600 text-sm mb-6 line-clamp-3 px-2">{gift.description}</p>
                    <div className="mt-auto w-full">
                        <button
                        onClick={() => isConfirmed ? setShowThankYouModal(true) : handleOpenGift(gift.id)}
                        disabled={isConfirmed && false} 
                        className={`w-full font-serif py-3 px-6 transition-colors flex items-center justify-center gap-2 uppercase tracking-widest text-xs
                            ${isConfirmed 
                                ? 'bg-green-600 text-white cursor-default' 
                                : 'bg-wedding-800 hover:bg-wedding-600 text-white'
                            }`}
                        >
                        {isConfirmed ? (
                            <><CheckCircle size={16} /> AGRADECEMOS O PRESENTE! ❤️</>
                        ) : (
                            <><GiftIcon size={16} /> Faça os noivos felizes</>
                        )}
                        </button>
                    </div>
                </div>
                </div>
            );
          })}
        </div>
      </div>

      {/* Thank You Modal */}
      <Modal
        isOpen={showThankYouModal}
        onClose={() => setShowThankYouModal(false)}
        title="Obrigado!"
      >
          <div className="text-center p-6 space-y-4">
               <Heart size={64} className="text-red-400 mx-auto animate-pulse" fill="#f87171" />
               <h3 className="font-serif text-2xl text-wedding-800">Obrigado a você que contribuiu com o nosso sonho!</h3>
               <p className="text-wedding-600">Cada gesto de carinho nos ajuda a construir nossa nova vida. Somos eternamente gratos por ter pessoas tão especiais ao nosso lado.</p>
          </div>
      </Modal>

      {/* Purchase Modal */}
      <Modal 
        isOpen={!!selectedGift} 
        onClose={() => !isSubmitting && setSelectedGift(null)}
        title="Presentear os Noivos"
      >
        {activeGift && (
          <div className="space-y-6 max-h-[80vh] overflow-y-auto px-1 custom-scrollbar">
            <div className="text-center">
              <div className="bg-wedding-50 p-4 rounded-full w-16 h-16 mx-auto flex items-center justify-center text-wedding-500 mb-4">
                <Heart size={32} fill="currentColor" />
              </div>
              <h4 className="font-serif text-xl text-wedding-800">Você escolheu: {activeGift.name}</h4>
              <p className="text-3xl font-serif text-wedding-800 mt-2">
